# python.tui.main (python/tui.py:56) — requirement 2-2
import sys
from types import SimpleNamespace
from unittest.mock import Mock

# Prevent audio backend initialization while importing the TUI module.
sys.modules.setdefault("sounddevice", SimpleNamespace())

import tui


def test_main_highlights_only_sounding_keys_and_cleans_up(monkeypatch):
    # meridian: unit_id=28faeb62248a requirement=2-2
    draws = []

    class FakeEngine:
        instances = []

        def __init__(self, on_state_change):
            self.on_state_change = on_state_change
            self.down = []
            self.up = []
            self.closed = False
            self.pending_s = False
            FakeEngine.instances.append(self)

        def key_down(self, key):
            self.down.append(key)
            if key == "a":
                self.on_state_change("a", True)
            elif key == "s":
                # Simulate a key waiting for the polyphony limit: no callback
                # means it must not be drawn as active yet.
                self.pending_s = True

        def key_up(self, key):
            self.up.append(key)
            if key == "a":
                self.on_state_change("a", False)
                if self.pending_s:
                    self.on_state_change("s", True)
            elif key == "s":
                self.on_state_change("s", False)

        def close(self):
            self.closed = True

    stdin = Mock()
    stdin.fileno.return_value = 17
    stdin.read.side_effect = ["a", "s", "q"]
    saved_terminal_state = object()
    tcgetattr = Mock(return_value=saved_terminal_state)
    tcsetattr = Mock()
    setcbreak = Mock()
    select_results = iter([
        ([stdin], [], []),  # press a: it sounds
        ([stdin], [], []),  # press s: it waits
        ([], [], []),       # a times out; waiting s begins sounding
        ([], [], []),       # s times out and stops
        ([stdin], [], []),  # quit
    ])
    clock_values = iter([0.0, 0.1, 0.6, 0.71, 0.8])

    monkeypatch.setattr(tui, "NoteEngine", FakeEngine)
    monkeypatch.setattr(tui.sys, "stdin", stdin)
    monkeypatch.setattr(tui.termios, "tcgetattr", tcgetattr)
    monkeypatch.setattr(tui.termios, "tcsetattr", tcsetattr)
    monkeypatch.setattr(tui.tty, "setcbreak", setcbreak)
    monkeypatch.setattr(tui.select, "select", lambda *args: next(select_results))
    monkeypatch.setattr(tui.time, "monotonic", lambda: next(clock_values))
    monkeypatch.setattr(tui, "_draw", lambda active: draws.append(tuple(sorted(active))))

    result = tui.main()

    assert result is None
    assert FakeEngine.instances[0].down == ["a", "s"]
    assert FakeEngine.instances[0].up == ["a", "s"]
    assert draws == [(), ("a",), (), ("s",), ()]
    tcgetattr.assert_called_once_with(17)
    setcbreak.assert_called_once_with(17)
    tcsetattr.assert_called_once_with(17, tui.termios.TCSADRAIN, saved_terminal_state)
    assert FakeEngine.instances[0].closed is True
